// Code node: "Build Emails" (Website contact forms). Mode: Run Once for All Items
const SUPPORT_EMAIL = 'consultation@iraideas.com';
const ADMIN_TO = 'iraideas@gmail.com';
const SITE_URL = 'https://iraideas.com';
const BOOK_URL = 'https://iraideas.com/retirement-certainty-session/';
const TZ = 'America/Phoenix';

const body = $('Webhook').first().json.body || {};
// Strip control characters (incl. CR/LF) so nothing can break out of an email header.
const clean = (v, max) => String(v ?? '').replace(/[\u0000-\u0009\u000B-\u001F\u007F]/g, '').trim().slice(0, max);
const oneLine = (v, max) => clean(v, max).replace(/[\r\n]+/g, ' ');
const EMAIL_OK = /^[A-Za-z0-9._%+'-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}$/;

const name = oneLine(body.name, 200);
const emailRaw = oneLine(body.email, 254);
const email = EMAIL_OK.test(emailRaw) ? emailRaw : '';
const phone = oneLine(body.phone, 50);
const message = clean(body.message, 2000);
const page = oneLine(body.page, 500);
const source = oneLine(body.source, 50);
const sourceLabel = { 'home-quick-contact': 'Homepage · Quick Contact', 'contact-page': 'Contact page · Send Us Your Query' }[source] || source || 'Website';

const esc = s => String(s ?? '').replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
const nl2br = s => esc(s).replace(/\r?\n/g, '<br>');
const when = new Date(body.submitted_at || Date.now());
const fWhen = new Intl.DateTimeFormat('en-US', { timeZone: TZ, weekday: 'long', month: 'long', day: 'numeric', year: 'numeric', hour: 'numeric', minute: '2-digit' }).format(when) + ' (Arizona)';
const first = name.split(/\s+/)[0] || '';
const telHref = 'tel:' + phone.replace(/[^\d+]/g, '');

const C = { ink: '#141312', ink2: '#46423c', muted: '#7a7469', gold: '#c9a45c', gold2: '#e4c98f', gold3: '#a9843f', ivory: '#f6f2ea', line: '#ebe4d7' };
const SERIF = "Georgia,'Times New Roman',serif";
const SANS = "-apple-system,'Segoe UI',Roboto,Helvetica,Arial,sans-serif";

const layout = ({ preheader, eyebrow, title, intro, body, footerNote }) => `<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="x-apple-disable-message-reformatting">
<title>${esc(title)}</title>
<style>
@media (max-width:620px){ .pss-pad{padding-left:22px!important;padding-right:22px!important} .pss-h1{font-size:24px!important} .pss-stack{display:block!important;width:auto!important} .pss-k{padding-bottom:0!important} .pss-v{padding-top:4px!important} .pss-btn{display:block!important;text-align:center!important;margin-bottom:8px!important} }
a{color:${C.gold3}}
</style></head>
<body style="margin:0;padding:0;background:${C.ivory};">
<div style="display:none;max-height:0;overflow:hidden;opacity:0;color:transparent">${esc(preheader)}</div>
<table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" style="background:${C.ivory};">
<tr><td align="center" style="padding:28px 12px;">
  <table role="presentation" width="600" cellpadding="0" cellspacing="0" border="0" style="width:100%;max-width:600px;background:#ffffff;border:1px solid ${C.line};border-radius:14px;overflow:hidden;">
    <tr><td style="background:${C.ink};background-image:linear-gradient(160deg,#221e16,#0d0d0e 70%);padding:24px 34px;" class="pss-pad">
      <table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0"><tr>
        <td style="font-family:${SERIF};font-size:22px;color:#ffffff;letter-spacing:.3px;">IRA <span style="color:${C.gold2};">Ideas</span></td>
        <td align="right" style="font-family:${SANS};font-size:11px;letter-spacing:2px;text-transform:uppercase;color:${C.gold};">Website Enquiry</td>
      </tr></table>
    </td></tr>
    <tr><td style="height:3px;line-height:3px;font-size:0;background:${C.gold};background-image:linear-gradient(90deg,${C.gold3},${C.gold2},${C.gold3});">&nbsp;</td></tr>
    <tr><td style="padding:34px 34px 6px;" class="pss-pad">
      <div style="font-family:${SANS};font-size:11px;font-weight:700;letter-spacing:2.2px;text-transform:uppercase;color:${C.gold3};">${eyebrow}</div>
      <h1 class="pss-h1" style="margin:10px 0 0;font-family:${SERIF};font-weight:normal;font-size:28px;line-height:1.25;color:${C.ink};">${title}</h1>
      ${intro ? `<p style="margin:14px 0 0;font-family:${SANS};font-size:15px;line-height:1.6;color:${C.ink2};">${intro}</p>` : ''}
    </td></tr>
    ${body}
    <tr><td style="padding:22px 34px 30px;border-top:1px solid ${C.line};" class="pss-pad">
      ${footerNote ? `<p style="margin:0 0 10px;font-family:${SANS};font-size:13px;line-height:1.6;color:${C.ink2};">${footerNote}</p>` : ''}
      <p style="margin:0;font-family:${SANS};font-size:11.5px;line-height:1.6;color:#9a958b;">IRA Ideas · <a href="${SITE_URL}" style="color:#9a958b;">iraideas.com</a></p>
    </td></tr>
  </table>
</td></tr></table>
</body></html>`;

const card = (rows, opts = {}) => `
    <tr><td style="padding:22px 34px 4px;" class="pss-pad">
      <table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" style="background:#fbf8f2;border:1px solid ${C.line};border-left:3px solid ${C.gold};border-radius:10px;">
        ${opts.heading ? `<tr><td colspan="2" style="padding:16px 20px 2px;font-family:${SANS};font-size:11px;font-weight:700;letter-spacing:2px;text-transform:uppercase;color:${C.gold3};">${opts.heading}</td></tr>` : ''}
        ${rows.map(([k, v], i) => `<tr>
          <td class="pss-stack pss-k" valign="top" style="padding:${i === 0 && !opts.heading ? 16 : 10}px 12px ${i === rows.length - 1 ? 16 : 10}px 20px;width:150px;font-family:${SANS};font-size:12px;font-weight:700;letter-spacing:.6px;text-transform:uppercase;color:${C.muted};">${k}</td>
          <td class="pss-stack pss-v" valign="top" style="padding:${i === 0 && !opts.heading ? 16 : 10}px 20px ${i === rows.length - 1 ? 16 : 10}px 20px;font-family:${SANS};font-size:15px;line-height:1.55;color:${C.ink};">${v}</td>
        </tr>`).join('')}
      </table>
    </td></tr>`;

const button = (href, label) => `<a href="${esc(href)}" class="pss-btn" style="display:inline-block;padding:13px 22px;border-radius:8px;font-family:${SANS};font-size:14px;font-weight:700;text-decoration:none;background:${C.ink};color:${C.gold2};">${label}</a>`;

// ---------- CLIENT CONFIRMATION ----------
// The visitor's message is deliberately NOT repeated here: anyone can type someone else's address
// into the form, and echoing the text would let them send arbitrary content through our Gmail.
const client_html = layout({
  preheader: 'Thanks for contacting IRA Ideas. We will be in touch soon.',
  eyebrow: 'Message received',
  title: 'Thank You for Reaching Out',
  intro: `Hi ${esc(first) || 'there'}, thank you for contacting IRA Ideas. We've received your message and will get back to you as soon as possible, usually within one business day.`,
  body:
    `
    <tr><td style="padding:18px 34px 4px;" class="pss-pad">
      <p style="margin:0 0 16px;font-family:${SANS};font-size:15px;line-height:1.6;color:${C.ink2};">If your question is time-sensitive, you can book a Retirement Certainty Session: up to 15 minutes with attorney Tim Berry on one self-directed IRA or 401(k) question.</p>
      ${button(BOOK_URL, 'Book a Retirement Certainty Session')}
    </td></tr>` +
    card([
      ['Email', `<a href="mailto:${esc(SUPPORT_EMAIL)}" style="color:${C.gold3};">${esc(SUPPORT_EMAIL)}</a>`],
      ['Phone', `<a href="tel:+16029001855" style="color:${C.ink};font-weight:700;text-decoration:none;">602-900-1855</a>`]
    ], { heading: 'Other ways to reach us' }),
  footerNote: `You're receiving this because this email address was entered on a contact form at iraideas.com. If that wasn't you, you can ignore this message.`
});

// ---------- ADMIN NOTIFICATION ----------
const admin_html = layout({
  preheader: `${name || email || 'Website visitor'} · ${sourceLabel}`,
  eyebrow: 'New enquiry',
  title: 'New Website Contact Form Submission',
  intro: `<b style="color:${C.ink};">${esc(name || email || 'A visitor')}</b> sent a message from the ${esc(sourceLabel)} form. Reply to this email to answer them directly.`,
  body:
    card([
      ...(name ? [['Name', esc(name)]] : []),
      ['Email', email ? `<a href="mailto:${esc(email)}" style="color:${C.gold3};">${esc(email)}</a>` : `<span style="color:${C.muted};">${esc(emailRaw) || '-'} (invalid)</span>`],
      ...(phone ? [['Phone', `<a href="${telHref}" style="color:${C.ink};font-weight:700;text-decoration:none;">${esc(phone)}</a>`]] : [])
    ], { heading: 'Contact' }) +
    card([
      ['Message', nl2br(message || '-')]
    ], { heading: 'Their message' }) +
    card([
      ['Form', esc(sourceLabel)],
      ['Page', esc(page || '-')],
      ['Received', esc(fWhen)],
      ['Country', esc(oneLine(body.ip_country, 10) || '-')]
    ], { heading: 'Details' }),
  footerNote: 'Submitted through iraideas.com'
});

return [{
  json: {
    client_email: email,
    client_subject: 'We received your message · IRA Ideas',
    client_html,
    admin_to: ADMIN_TO,
    admin_reply_to: email,
    admin_subject: `New website enquiry: ${name || email || 'visitor'} · ${sourceLabel}`,
    admin_html
  }
}];

// Code node: "Gmail: Prepare Send" — builds raw MIME so mail goes out from the alias below.
const FROM_NAME  = 'IRA Ideas';
const FROM_EMAIL = 'consultation@iraideas.com';   // must be a "Send mail as" alias in Gmail
const CLIENT_REPLY_TO = 'consultation@iraideas.com';

// ---------------------------------------------------------------------
const b64 = s => Buffer.from(s, 'utf8').toString('base64');
const enc = s => /^[\x20-\x7E]*$/.test(s) ? s : '=?UTF-8?B?' + b64(s) + '?=';   // safe headers (·, accents)
const wrap = s => s.replace(/.{1,76}/g, '$&\r\n');
const hdr = s => String(s ?? '').replace(/[\r\n]+/g, ' ').trim();                  // no header injection

function buildRaw(to, replyTo, subject, html) {
  const lines = [
    `From: ${enc(FROM_NAME)} <${FROM_EMAIL}>`,
    `To: ${hdr(to)}`,
    ...(replyTo ? [`Reply-To: ${hdr(replyTo)}`] : []),
    `Subject: ${enc(hdr(subject))}`,
    'MIME-Version: 1.0',
    'Content-Type: text/html; charset="UTF-8"',
    'Content-Transfer-Encoding: base64',
    '',
    wrap(b64(html))
  ];
  return Buffer.from(lines.join('\r\n'), 'utf8').toString('base64')
    .replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
}

const out = [];
for (const item of $input.all()) {
  const j = item.json || {};
  if (j.admin_to && j.admin_subject && j.admin_html) {
    out.push({ json: { who: 'admin', to: j.admin_to, raw: buildRaw(j.admin_to, j.admin_reply_to, j.admin_subject, j.admin_html) } });
  }
  if (j.client_email && j.client_subject && j.client_html) {
    out.push({ json: { who: 'client', to: j.client_email, raw: buildRaw(j.client_email, CLIENT_REPLY_TO, j.client_subject, j.client_html) } });
  }
}
return out;
